import React, { useContext } from "react"; // useContext add kiya gaya hai
import GeneralContext from "./GeneralContext"; // Context import kiya
import "./BuyActionWindow.css";

const BuyActionWindow = ({ uid }) => {
  // Context se functions nikalne ka sahi tarika
  const { closeBuyWindow } = useContext(GeneralContext);

  // handleBuyClick ko define kiya (Jo error aa raha tha)
  const handleBuyClick = () => {
    console.log("Buying stock with UID:", uid);
    // Yahan future mein API call aayegi
    closeBuyWindow(); // Buy hone par window band ho jaye
  };

  const handleCancelClick = () => {
    closeBuyWindow(); // Cancel button ke liye
  };

  return (
    <div className="container" id="buy-window" draggable="true">
      <div className="regular-order">
        <div className="inputs">
          <fieldset>
            <legend>Qty.</legend>
            <input type="number" name="qty" id="qty" defaultValue="1" />
          </fieldset>
          <fieldset>
            <legend>Price</legend>
            <input type="number" name="price" id="price" step="0.05" defaultValue="0.00" />
          </fieldset>
        </div>
      </div>

      <div className="buttons">
        <span>Margin required ₹140.65</span>
        <div>
          {/* Button tag use karna better hai functionality ke liye */}
          <button className="btn btn-blue" onClick={handleBuyClick}>
            Buy
          </button>
          <button className="btn btn-grey" onClick={handleCancelClick}>
            Cancel
          </button>
        </div>
      </div>
    </div>
  );
};

export default BuyActionWindow;
